UPDATE public.quizzes SET questions = questions || '[{"id": 191, "question": "(Q191) Quelle est la durée légale du travail hebdomadaire en France selon la Partie Législative ?", "options": ["35 heures par semaine", "39 heures par semaine", "40 heures par semaine", "32 heures par semaine"], "correct_index": 0, "casus": "[Heures supplémentaires] Un salarié travaillant dans une entreprise de logistique effectue 39 heures de travail effectif au cours d''une semaine donnée. Il demande à son employeur comment sont décomptées les heures au-delà de la durée légale.", "reference": "Art. L3121-27", "article": "La durée légale du travail effectif des salariés à temps complet est fixée à trente-cinq heures par semaine."}]'::jsonb WHERE id = 8;